// webviewMCPClient.ts
const vscode = acquireVsCodeApi();

export function callMCP(tool: string, args: object): Promise<any> {
  return new Promise((resolve, reject) => {
    const id = generateId();

    const handler = (event: MessageEvent) => {
      if (event.data.type === 'mcpResult' && event.data.id === id) {
        window.removeEventListener('message', handler);
        if (event.data.error) {
          reject(new Error(event.data.error));
        } else {
          resolve(event.data.result);
        }
      }
    };

    window.addEventListener('message', handler);
    vscode.postMessage({ type: 'mcpCall', id, tool, args });
  });
}

// 请求消息格式
{
  type: 'mcpCall',
  id: 'unique-request-id',
  tool: 'tool_name',
  args: { param1: 'value1' }
}

// 响应消息格式
{
  type: 'mcpResult',
  id: 'unique-request-id',
  success: true,
  result: { data: '...' }
}

// 错误响应格式
{
  type: 'mcpResult',
  id: 'unique-request-id',
  success: false,
  error: 'Error message'
}

// store/workflowStore.ts
import { create } from 'zustand';
import { immer } from 'zustand/middleware/immer';

interface WorkflowState {
  steps: Step[];
  currentStep: number;
  loading: boolean;
  error: string | null;
  fetchSteps: () => Promise<void>;
  setCurrentStep: (step: number) => void;
}

export const useWorkflowStore = create<WorkflowState>()(
  immer((set, get) => ({
    steps: [],
    currentStep: 0,
    loading: false,
    error: null,

    fetchSteps: async () => {
      set({ loading: true, error: null });
      try {
        const result = await callMCP('workflow.get_steps', {});
        set({ steps: result.steps, loading: false });
      } catch (err) {
        set({ error: err.message, loading: false });
      }
    },

    setCurrentStep: (step) => set({ currentStep: step }),
  }))
);

